import whisper

def transcribe_audio(audio_path):
    model = whisper.load_model("base")
    result = model.transcribe(audio_path)
    return result["text"]

def text_to_speech(text, output_path):
    # 使用TTS服务
    import gtts
    tts = gtts.gTTS(text, lang='zh-cn')
    tts.save(output_path)
```

